namespace {
using J=TSharedPtr<FJsonObject>;
J Object(const J& O,const TCHAR* K){const J* V=nullptr;return O.IsValid()&&O->TryGetObjectField(K,V)?*V:nullptr;}
TArray<TSharedPtr<FJsonValue>> Array(const J& O,const TCHAR* K){const TArray<TSharedPtr<FJsonValue>>* V=nullptr;return O.IsValid()&&O->TryGetArrayField(K,V)?*V:TArray<TSharedPtr<FJsonValue>>{};}
double Number(const J& O,const TCHAR* K,double F=0){if(O.IsValid())O->TryGetNumberField(K,F);return F;}
FString String(const J& O,const TCHAR* K){FString S;if(O.IsValid())O->TryGetStringField(K,S);return S;}
bool Flag(const J& O,const TCHAR* K){bool B=false;if(O.IsValid())O->TryGetBoolField(K,B);return B;}
double At(const TArray<TSharedPtr<FJsonValue>>& A,int32 I,double F=0){return A.IsValidIndex(I)&&A[I]->Type==EJson::Number?A[I]->AsNumber():F;}
FVector Point(const TArray<TSharedPtr<FJsonValue>>& A,double Scale=100){return FVector(At(A,0),At(A,2),At(A,1))*Scale;}
J Read(const FString& Path){FString S;J O;if(FFileHelper::LoadFileToString(S,*Path))FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(S),O);return O;}
double ControlTime(double Time,const J& Spec){const double Start=Number(Spec,TEXT("start")),Stop=Number(Spec,TEXT("stop"),Time),Span=FMath::Max(.0001,Stop-Start);double T=Time*Number(Spec,TEXT("frequency"),1)+Number(Spec,TEXT("phase"));const FString Cycle=String(Spec,TEXT("cycle"));if(Cycle==TEXT("clamp"))return FMath::Clamp(T,Start,Stop);if(Cycle==TEXT("reverse")){double U=FMath::Fmod(FMath::Max(0.,T-Start),Span*2);return Start+(U<=Span?U:2*Span-U);}return Start+FMath::Fmod(FMath::Max(0.,T-Start),Span);}
TArray<TSharedPtr<FJsonValue>> Key(const TArray<TSharedPtr<FJsonValue>>& Keys,double T){TArray<TSharedPtr<FJsonValue>> Out;for(auto V:Keys){if(V->Type!=EJson::Array)continue;auto Row=V->AsArray();if(!Out.IsEmpty()&&At(Row,0)>T)break;Out=Row;}return Out;}
FLinearColor Color(const TArray<TSharedPtr<FJsonValue>>& A,FLinearColor F=FLinearColor::White){return A.Num()>=3?FLinearColor(At(A,0),At(A,1),At(A,2),At(A,3,1)):F;}
FTransform Frame(const TArray<TSharedPtr<FJsonValue>>& F){return FTransform(FQuat(-At(F,4),-At(F,6),-At(F,5),At(F,7,1)).GetNormalized(),FVector(At(F,1),At(F,3),At(F,2))*100,FVector(At(F,8,1)));}
FString BoneKey(FString S){S.ReplaceInline(TEXT("-"),TEXT(""));S.ReplaceInline(TEXT("_"),TEXT(""));S.ReplaceInline(TEXT(" "),TEXT(""));return S.ToLower();}
float Random(int32 Seed,int32 Salt){return float(GetTypeHash(uint32(Seed)*747796405u+uint32(Salt)*2891336453u)&0xffffff)/float(0xffffff);}
}

// Original NIF data rendered as bounded procedural sections: one draw per original
// mesh/emitter, never one actor/draw per spark. These components cannot collide.
class FBridgeSpellVisuals {
    struct FPart {TWeakObjectPtr<UProceduralMeshComponent> Mesh;TWeakObjectPtr<UMaterialInstanceDynamic> Material;J Spec;bool Particle=false,Created=false;TArray<FVector> Base,Normals;TArray<FVector2D> UV;TArray<FLinearColor> Colors;TArray<int32> Indices;TArray<TArray<FVector>> Morphs;int32 Slots=0;};
    struct FEffect {TWeakObjectPtr<AActor> Actor;FString Owner,Target;J Def;TArray<FPart> Parts;double Began=0,Duration=3;bool Gather=false,Projectile=false,Weapon=false;TWeakObjectPtr<UMeshComponent> Attachment;FTransform WeaponFrame;int32 WeaponId=0;FVector Start;float Scale=1;};
    UDAoCBridgeSubsystem* S;FString Folder;J Catalog;TMap<FString,J> Data;TArray<FEffect> Live;TMap<FString,double> Bursts;int64 LastSequence=0;int32 Created=0,Culled=0,Particles=0;double LastMs=0,PeakMs=0;
    AActor* Entity(const FString& Id)const{auto* P=S->Entities.Find(Id);return P&&IsValid(*P)?P->Get():nullptr;}
    FVector Anchor(AActor* A,const J& Def,FQuat& Rotation)const{
        Rotation=A->GetActorQuat();const FString Name=String(Def,TEXT("node"));float Height=180;USkeletalMeshComponent* Mesh=nullptr;if(auto* K=Cast<ASkeletalMeshActor>(A)){Mesh=K->GetSkeletalMeshComponent();Height=FMath::Clamp(float(Mesh->Bounds.BoxExtent.Z*2),15.f,600.f);}
        if(Mesh&&Name.StartsWith(TEXT("Bip01"))){TArray<FName> Names;Mesh->GetBoneNames(Names);for(auto B:Names)if(BoneKey(B.ToString())==BoneKey(Name)){auto T=Mesh->GetSocketTransform(B,RTS_World);Rotation=T.GetRotation();return T.GetLocation();}}
        return A->GetActorLocation()+FVector(0,0,Name.Contains(TEXT("chest"))?Height*.6:Name.Contains(TEXT("head"))?Height*.9:0);
    }
    FVector Chest(AActor* A)const{double H=180;if(auto* K=Cast<ASkeletalMeshActor>(A))H=FMath::Clamp(K->GetSkeletalMeshComponent()->Bounds.BoxExtent.Z*2,15.,600.);return A->GetActorLocation()+FVector(0,0,H*.6);}
    void DropGather(const FString& Owner){for(int32 I=Live.Num()-1;I>=0;--I)if(Live[I].Owner==Owner&&Live[I].Gather){if(Live[I].Actor.IsValid())Live[I].Actor->Destroy();Live.RemoveAt(I);}}
    UMaterialInstanceDynamic* Material(AActor* Actor,const J& Spec,bool Particle){const FString Blend=Particle?String(Spec,TEXT("blend")):String(Object(Spec,TEXT("material")),TEXT("alpha"));const TCHAR* Path=Blend==TEXT("add")?TEXT("/DAoCVisualBridge/SpellVisuals_v01/M_SpellAdd.M_SpellAdd"):TEXT("/DAoCVisualBridge/SpellVisuals_v01/M_SpellAlpha.M_SpellAlpha");auto* Base=LoadObject<UMaterialInterface>(nullptr,Path);if(!Base)return nullptr;auto* M=UMaterialInstanceDynamic::Create(Base,Actor);FString Key=String(Spec,TEXT("texture_key")),TexturePath;auto Textures=Object(Catalog,TEXT("textures"));if(Textures.IsValid())Textures->TryGetStringField(Key,TexturePath);if(!TexturePath.IsEmpty())if(auto* T=LoadObject<UTexture2D>(nullptr,*TexturePath))M->SetTextureParameterValue(TEXT("Sprite"),T);return M;}
    void BuildParts(FEffect& E,const J& Resource){
        for(int32 Kind=0;Kind<2;++Kind)for(auto V:Array(Resource,Kind?TEXT("particles"):TEXT("parts"))){if(V->Type!=EJson::Object)continue;FPart Part;Part.Spec=V->AsObject();Part.Particle=Kind==1;auto* C=NewObject<UProceduralMeshComponent>(E.Actor.Get());E.Actor->AddInstanceComponent(C);if(!E.Actor->GetRootComponent())E.Actor->SetRootComponent(C);else C->SetupAttachment(E.Actor->GetRootComponent());C->SetCollisionEnabled(ECollisionEnabled::NoCollision);C->SetGenerateOverlapEvents(false);C->SetCastShadow(false);C->SetCanEverAffectNavigation(false);C->SetReceivesDecals(false);C->RegisterComponent();Part.Mesh=C;auto* M=Material(E.Actor.Get(),Part.Spec,Part.Particle);Part.Material=M;if(M)C->SetMaterial(0,M);
            if(Part.Particle){const double Lifetime=Number(Part.Spec,TEXT("lifetime"),1)+Number(Part.Spec,TEXT("lifetime_random"));Part.Slots=FMath::Clamp(int32(FMath::CeilToDouble(Lifetime*Number(Part.Spec,TEXT("emit_rate"),10)))+1,1,S->Quality==TEXT("accessible")?24:48);Part.Slots=FMath::Min(Part.Slots,int32(Number(Part.Spec,TEXT("max_particles"),Part.Slots)));for(int32 I=0;I<Part.Slots;++I){Part.Indices.Append({I*4,I*4+1,I*4+2,I*4,I*4+2,I*4+3});Part.UV.Append({{0,0},{1,0},{1,1},{0,1}});}}
            else{for(auto X:Array(Part.Spec,TEXT("positions")))Part.Base.Add(Point(X->AsArray()));for(auto X:Array(Part.Spec,TEXT("normals")))Part.Normals.Add(Point(X->AsArray(),1));for(auto X:Array(Part.Spec,TEXT("uvs"))){auto UV=X->AsArray();Part.UV.Add({At(UV,0),At(UV,1)});}for(auto X:Array(Part.Spec,TEXT("colors")))Part.Colors.Add(Color(X->AsArray()));for(auto X:Array(Part.Spec,TEXT("indices")))Part.Indices.Add(int32(X->AsNumber()));for(auto X:Array(Part.Spec,TEXT("morph_targets"))){TArray<FVector> Delta;for(auto Y:X->AsArray())Delta.Add(Point(Y->AsArray()));Part.Morphs.Add(Delta);}}
            E.Parts.Add(MoveTemp(Part));}
    }
    void Add(int32 Fx,const FString& Owner,const FString& Target,double Age,bool Gather=false,double Duration=0,bool Projectile=false){
        auto* A=Entity(Owner);auto Def=Object(Object(Catalog,TEXT("fx")),*FString::FromInt(Fx));if(!A||!Def.IsValid())return;
        const int32 Limit=S->Quality==TEXT("accessible")?24:S->Quality==TEXT("balanced")?40:64;
        if(Live.Num()>=Limit||FVector::DistSquared(A->GetActorLocation(),S->PlayerPosition)>FMath::Square(Owner==TEXT("player:local")?15000.:8000.)){++Culled;return;}
        const FString Id=String(Def,TEXT("data"));J Resource=Data.FindRef(Id);if(!Resource.IsValid()){Resource=Read(Folder/TEXT("Data")/(Id+TEXT(".json")));if(!Resource.IsValid())return;Data.Add(Id,Resource);}
        FEffect E;E.Owner=Owner;E.Target=Target;E.Def=Def;E.Gather=Gather;E.Projectile=Projectile;E.Began=FPlatformTime::Seconds()-Age;E.Duration=Duration>0?Duration:Number(Def,TEXT("duration_s"),3);if(E.Duration<=0)E.Duration=3;
        if(Age>E.Duration)return;FQuat Rotation;E.Start=Projectile?Chest(A):Anchor(A,Def,Rotation);if(Flag(Def,TEXT("autoscale")))if(auto* K=Cast<ASkeletalMeshActor>(A)){auto* Row=S->EntityRows.Find(Owner);const FString Model=FString::FromInt(int32(Row?Number(*Row,TEXT("model_id")):0));auto Figures=Object(Catalog,TEXT("figure_models"));E.Scale=Owner.StartsWith(TEXT("player:"))||(Figures.IsValid()&&Figures->HasField(Model))?A->GetActorScale3D().GetAbsMax():FMath::Clamp(float(K->GetSkeletalMeshComponent()->Bounds.BoxExtent.Z*2/185),.08f,3.f);}
        FActorSpawnParameters P;P.ObjectFlags|=RF_Transient;P.SpawnCollisionHandlingOverride=ESpawnActorCollisionHandlingMethod::AlwaysSpawn;E.Actor=S->GetWorld()->SpawnActor<AActor>(E.Start,Rotation.Rotator(),P);if(!E.Actor.IsValid())return;
        BuildParts(E,Resource);
        Live.Add(MoveTemp(E));++Created;
    }
    bool ReadWeaponFrame(const J& Def,FTransform& Out)const{
        auto F=Object(Def,TEXT("effect_frame"));auto Basis=Array(F,TEXT("basis")),T=Array(F,TEXT("translation_cm"));if(Basis.Num()!=3||T.Num()!=3)return false;FMatrix M=FMatrix::Identity;
        for(int32 I=0;I<3;++I){auto Axis=Basis[I]->AsArray();if(Axis.Num()!=3)return false;M.SetAxis(I,FVector(At(Axis,0),At(Axis,1),At(Axis,2)));}M.SetOrigin(FVector(At(T,0),At(T,1),At(T,2)));Out=FTransform(M);return Out.IsValid();
    }
    bool WeaponNear(const FString& Owner)const{auto* A=Entity(Owner);return A&&(Owner==TEXT("player:local")||FVector::DistSquared(A->GetActorLocation(),S->PlayerPosition)<FMath::Square(S->Quality==TEXT("accessible")?4000.:S->Quality==TEXT("balanced")?6000.:8000.));}
    void SyncWeapons(){
        for(int32 I=Live.Num()-1;I>=0;--I)if(Live[I].Weapon&&(!Live[I].Attachment.IsValid()||!WeaponNear(Live[I].Owner))){if(Live[I].Actor.IsValid())Live[I].Actor->Destroy();Live.RemoveAt(I);}
        int32 Count=0;for(const auto& E:Live)if(E.Weapon)++Count;const int32 Limit=S->Quality==TEXT("accessible")?8:S->Quality==TEXT("balanced")?16:24;
        auto Visit=[&](const FString& Owner,const auto& Bindings){if(!WeaponNear(Owner))return;for(const auto& Pair:Bindings){const auto& Binding=Pair.Value;if(Binding.Effect<=0||!Binding.Component.IsValid())continue;bool Existing=false;for(const auto& E:Live)if(E.Weapon&&E.Attachment==Binding.Component&&E.WeaponId==Binding.Effect){Existing=true;break;}if(Existing||Count>=Limit)continue;
            auto Def=Object(Object(Catalog,TEXT("weapon_effects")),*FString::FromInt(Binding.Effect));FTransform Grip;if(!Def||!ReadWeaponFrame(Binding.Descriptor,Grip))continue;const FString Id=String(Def,TEXT("data"));J Resource=Data.FindRef(Id);if(!Resource){Resource=Read(Folder/TEXT("Data")/(Id+TEXT(".json")));if(!Resource)continue;Data.Add(Id,Resource);}
            FEffect E;E.Owner=Owner;E.Def=Def;E.Weapon=true;E.WeaponId=Binding.Effect;E.Attachment=Binding.Component;E.WeaponFrame=Grip;E.Began=FPlatformTime::Seconds();E.Duration=TNumericLimits<double>::Max();const FTransform World=Grip*Binding.Component->GetComponentTransform();FActorSpawnParameters P;P.ObjectFlags|=RF_Transient;P.SpawnCollisionHandlingOverride=ESpawnActorCollisionHandlingMethod::AlwaysSpawn;E.Actor=S->GetWorld()->SpawnActor<AActor>(World.GetLocation(),World.Rotator(),P);if(!E.Actor.IsValid())continue;BuildParts(E,Resource);Live.Add(MoveTemp(E));++Created;++Count;
        }};
        Visit(TEXT("player:local"),S->LocalEquipment);for(const auto& Pair:S->RemoteEquipment)Visit(Pair.Key,Pair.Value.Bindings);
    }
    void Mesh(FPart& P,double Age){
        if(!P.Mesh.IsValid())return;auto Anim=Object(P.Spec,TEXT("anim"));auto Mat=Object(P.Spec,TEXT("material"));const auto Vis=Array(Anim,TEXT("vis"));if(!Vis.IsEmpty()){auto K=Key(Vis,ControlTime(Age,Object(Anim,TEXT("vis_timing"))));P.Mesh->SetVisibility(At(K,1)!=0);}else P.Mesh->SetVisibility(true);
        FTransform Transform;auto Node=Object(P.Spec,TEXT("node"));auto T=Array(Node,TEXT("translation")),Q=Array(Node,TEXT("rotation")),Scale=Array(Node,TEXT("scale"));Transform=FTransform(FQuat(-At(Q,0),-At(Q,2),-At(Q,1),At(Q,3,1)).GetNormalized(),Point(T),FVector(At(Scale,0,1),At(Scale,2,1),At(Scale,1,1)));
        const auto Frames=Array(Anim,TEXT("frames"));if(!Frames.IsEmpty())Transform=Frame(Key(Frames,ControlTime(Age,Object(Anim,TEXT("timing")))));
        TArray<FVector> Vertices=P.Base;auto Morph=Object(P.Spec,TEXT("morph"));const auto Times=Array(Morph,TEXT("times")),Weights=Array(Morph,TEXT("weights"));if(Times.Num()>0&&Times.Num()==Weights.Num()){double Time=ControlTime(Age,Morph);int32 K=0;while(K+1<Times.Num()&&At(Times,K+1)<=Time)++K;int32 Next=FMath::Min(K+1,Times.Num()-1);double F=Next==K?0:FMath::Clamp((Time-At(Times,K))/FMath::Max(.0001,At(Times,Next)-At(Times,K)),0.,1.);auto A=Weights[K]->AsArray(),B=Weights[Next]->AsArray();for(int32 M=0;M<P.Morphs.Num();++M){double W=FMath::Lerp(At(A,M),At(B,M),F);if(W==0||P.Morphs[M].Num()!=Vertices.Num())continue;for(int32 I=0;I<Vertices.Num();++I)Vertices[I]+=P.Morphs[M][I]*W;}}
        for(auto& V:Vertices)V=Transform.TransformPosition(V);FLinearColor Tint=Color(Array(Mat,TEXT("tint")));float Opacity=Number(Mat,TEXT("opacity"),1);auto Alpha=Object(Mat,TEXT("alpha_anim"));auto Keys=Array(Alpha,TEXT("keys"));if(!Keys.IsEmpty())Opacity=At(Key(Keys,ControlTime(Age,Alpha)),1,Opacity);
        for(auto X:Array(Mat,TEXT("color_anims"))){auto A=X->AsObject();auto K=Key(Array(A,TEXT("keys")),ControlTime(Age,A));if(K.Num()>=4)Tint=FLinearColor(At(K,1),At(K,2),At(K,3),1);}
        if(P.Material.IsValid()){P.Material->SetVectorParameterValue(TEXT("Tint"),Tint);P.Material->SetScalarParameterValue(TEXT("Opacity"),Opacity);}
        TArray<FLinearColor> Colors=P.Colors;if(Colors.Num()!=Vertices.Num())Colors.Init(FLinearColor::White,Vertices.Num());Upload(P,Vertices,Colors);
    }
    void Upload(FPart& P,const TArray<FVector>& Vertices,const TArray<FLinearColor>& Colors){if(!P.Mesh.IsValid()||Vertices.IsEmpty())return;TArray<FProcMeshTangent> Tangents;TArray<FVector> Normals=P.Normals;if(Normals.Num()!=Vertices.Num())Normals.Init(FVector::UpVector,Vertices.Num());if(!P.Created){P.Mesh->CreateMeshSection_LinearColor(0,Vertices,P.Indices,Normals,P.UV,Colors,Tangents,false);P.Created=true;}else P.Mesh->UpdateMeshSection_LinearColor(0,Vertices,Normals,P.UV,Colors,Tangents);}
    void Sprites(FPart& P,double Age,const FTransform& World,bool Persistent=false){
        if(!P.Mesh.IsValid())return;TArray<FVector> V;TArray<FLinearColor> Colors;V.SetNumZeroed(P.Slots*4);Colors.Init(FLinearColor::Transparent,P.Slots*4);const double Cycle=Persistent?0:Number(P.Spec,TEXT("cycle"));double T=Cycle>0?FMath::Fmod(Age,Cycle):Age;const double Rate=FMath::Max(.1,Number(P.Spec,TEXT("emit_rate"),10));int32 Last=FMath::FloorToInt(T*Rate);auto Emitter=Object(P.Spec,TEXT("emitter"));FVector Origin=Point(Array(Emitter,TEXT("origin")));FTransform E;auto EA=Object(P.Spec,TEXT("emitter_anim"));if(!Array(EA,TEXT("frames")).IsEmpty())E=Frame(Key(Array(EA,TEXT("frames")),ControlTime(T,EA)));else{auto Basis=Array(Emitter,TEXT("basis"));if(Basis.Num()==3){FMatrix M=FMatrix::Identity;M.SetAxis(0,Point(Basis[0]->AsArray(),1));M.SetAxis(1,Point(Basis[2]->AsArray(),1));M.SetAxis(2,Point(Basis[1]->AsArray(),1));E=FTransform(M);}E.SetTranslation(Origin);}
        FVector Right=FVector::RightVector,Up=FVector::UpVector;if(IsValid(S->Camera)){Right=World.InverseTransformVectorNoScale(S->Camera->GetActorRightVector());Up=World.InverseTransformVectorNoScale(S->Camera->GetActorUpVector());}
        const FVector Box=Point(Array(P.Spec,TEXT("box")));for(int32 I=0;I<P.Slots;++I){int32 Seed=Last-I;double Born=Seed/Rate,Life=Number(P.Spec,TEXT("lifetime"),1)+Random(Seed,1)*Number(P.Spec,TEXT("lifetime_random")),AgeP=T-Born;if(Seed<0||AgeP<0||AgeP>=Life||(!Persistent&&(Born<Number(P.Spec,TEXT("emit_start"))||Born>=FMath::Max(Number(P.Spec,TEXT("emit_stop"),3),Number(P.Spec,TEXT("emit_start"))+1/30.))))continue;
            double Decl=Number(P.Spec,TEXT("declination"))+(Random(Seed,2)*2-1)*Number(P.Spec,TEXT("declination_variation")),Plan=Number(P.Spec,TEXT("planar_angle"))+(Random(Seed,3)*2-1)*Number(P.Spec,TEXT("planar_angle_variation"));FVector Direction(FMath::Sin(Decl)*FMath::Cos(Plan),FMath::Sin(Decl)*FMath::Sin(Plan),FMath::Cos(Decl));double Speed=100*(Number(P.Spec,TEXT("speed"))+(Random(Seed,4)*2-1)*Number(P.Spec,TEXT("speed_random")));FVector Position=FVector((Random(Seed,5)-.5)*Box.X,(Random(Seed,6)-.5)*Box.Y,(Random(Seed,7)-.5)*Box.Z)+Direction*Speed*AgeP;
            FLinearColor C=FLinearColor::White;double Size=Number(P.Spec,TEXT("size"),.1)*100,Spin=0;for(auto X:Array(P.Spec,TEXT("modifiers"))){auto M=X->AsObject();const FString Type=String(M,TEXT("type"));if(Type==TEXT("growfade")){double Grow=Number(M,TEXT("grow")),Fade=Number(M,TEXT("fade"));Size*=Grow>0?FMath::Min(1.,AgeP/Grow):1;Size*=Fade>0?FMath::Min(1.,(Life-AgeP)/Fade):1;}else if(Type==TEXT("rotation"))Spin=AgeP*Number(M,TEXT("speed"))+Random(Seed,8)*PI*2;else if(Type==TEXT("color")){auto K=Array(M,TEXT("keys"));double Fraction=AgeP/FMath::Max(.001,Life);auto A=Key(K,Fraction);int32 Index=0;while(Index+1<K.Num()&&At(K[Index+1]->AsArray(),0)<=Fraction)++Index;if(A.Num()>1&&A[1]->Type==EJson::Array){C=Color(A[1]->AsArray());if(K.IsValidIndex(Index+1)){auto B=K[Index+1]->AsArray();double F=FMath::Clamp((Fraction-At(A,0))/FMath::Max(.001,At(B,0)-At(A,0)),0.,1.);C=FMath::Lerp(C,Color(B[1]->AsArray()),float(F));}}}}
            Position=E.TransformPosition(Position);FVector R=(Right*FMath::Cos(Spin)+Up*FMath::Sin(Spin))*Size*.5,U=(Up*FMath::Cos(Spin)-Right*FMath::Sin(Spin))*Size*.5;V[I*4]=Position-R-U;V[I*4+1]=Position+R-U;V[I*4+2]=Position+R+U;V[I*4+3]=Position-R+U;for(int32 J=0;J<4;++J)Colors[I*4+J]=C;++Particles;}
        Upload(P,V,Colors);
    }
public:
    explicit FBridgeSpellVisuals(UDAoCBridgeSubsystem* Owner):S(Owner){Folder=FPaths::ProjectPluginsDir()/TEXT("DAoCVisualBridge/Content/SpellVisuals_v01");Catalog=Read(Folder/TEXT("catalog.json"));}
    ~FBridgeSpellVisuals(){Clear();}
    void Clear(){for(auto& E:Live)if(E.Actor.IsValid())E.Actor->Destroy();Live.Empty();Bursts.Empty();LastSequence=0;}
    void Apply(const J& Snapshot){for(auto V:Array(Snapshot,TEXT("spell_visuals"))){if(V->Type!=EJson::Object)continue;auto E=V->AsObject();int64 Seq=int64(Number(E,TEXT("seq")));if(Seq<=LastSequence)continue;LastSequence=Seq;double Age=Number(E,TEXT("age_ms"))/1000;if(Age<0||Age>8)continue;FString Kind=String(E,TEXT("kind")),Caster=String(E,TEXT("caster")),Target=String(E,TEXT("target"));if(Kind==TEXT("cancel")){DropGather(Caster);continue;}int32 Id=int32(Number(E,TEXT("effect_id")));auto Def=Object(Object(Catalog,TEXT("effects")),*FString::FromInt(Id));if(!Def.IsValid())continue;
            if(Kind==TEXT("cast")){DropGather(Caster);double Duration=Number(E,TEXT("duration_ms"))/1000;if(Duration>0)for(auto X:Array(Def,TEXT("gather")))Add(int32(X->AsNumber()),Caster,TEXT(""),Age,true,Duration+1.5);}
            else if(Kind==TEXT("release")){DropGather(Caster);const FString Key=Caster+TEXT(":")+FString::FromInt(Id);double Now=FPlatformTime::Seconds();if(Now-Bursts.FindRef(Key)>.25){for(auto X:Array(Def,TEXT("cast_fx")))Add(int32(X->AsNumber()),Caster,Target,Age);Bursts.Add(Key,Now);}double Delay=Number(Def,TEXT("release_s"));int32 Projectile=int32(Number(Def,TEXT("projectile")));if(Projectile>0){auto* A=Entity(Caster);auto* B=Entity(Target);if(A&&B){double Travel=FVector::Distance(A->GetActorLocation(),B->GetActorLocation())/2125.;Add(Projectile,Caster,Target,Age-Delay,false,FMath::Max(.05,Travel),true);Delay+=Travel;}}Add(int32(Number(Def,Flag(E,TEXT("resisted"))?TEXT("resist"):TEXT("target"))),Target,Caster,Age-Delay);if(!Flag(E,TEXT("resisted")))Add(int32(Number(Def,TEXT("buildup"))),Target,Caster,Age-Delay);}
        }}
    void Tick(float Dt){double Began=FPlatformTime::Seconds();Particles=0;SyncWeapons();for(auto It=Bursts.CreateIterator();It;++It)if(Began-It.Value()>2)It.RemoveCurrent();for(int32 I=Live.Num()-1;I>=0;--I){auto& E=Live[I];auto* Owner=Entity(E.Owner);double Age=Began-E.Began;if(!Owner||!E.Actor.IsValid()||Age>E.Duration){if(E.Actor.IsValid())E.Actor->Destroy();Live.RemoveAt(I);continue;}E.Actor->SetActorHiddenInGame(Age<0);if(Age<0)continue;if(E.Weapon){if(!E.Attachment.IsValid()){E.Actor->Destroy();Live.RemoveAt(I);continue;}const FTransform World=E.WeaponFrame*E.Attachment->GetComponentTransform();E.Actor->SetActorTransform(World);for(auto& Part:E.Parts)if(Part.Particle)Sprites(Part,Age,World,true);else Mesh(Part,Age);continue;}FQuat Rotation;FVector P=Anchor(Owner,E.Def,Rotation);auto* Target=Entity(E.Target);if(Target&&(E.Projectile||Number(E.Def,TEXT("track"))>0)){FVector Goal=Chest(Target);FVector Direction=(Goal-P).GetSafeNormal();if(!Direction.IsNearlyZero())Rotation=FRotationMatrix::MakeFromYZ(-Direction,FVector::UpVector).ToQuat();if(E.Projectile)P=FMath::Lerp(E.Start,Goal,FMath::Clamp(Age/E.Duration,0.,1.));}FTransform World(Rotation,P,FVector(E.Scale));E.Actor->SetActorTransform(World);double T=Age;if(E.Gather){double Cycle=Number(E.Def,TEXT("duration_s"),4);if(Cycle>0)T=FMath::Fmod(T,Cycle);}for(auto& Part:E.Parts)if(Part.Particle)Sprites(Part,T,World);else Mesh(Part,T);}LastMs=(FPlatformTime::Seconds()-Began)*1000;PeakMs=FMath::Max(PeakMs,LastMs);}
    J Test(){int32 Checks=0;TArray<TSharedPtr<FJsonValue>> Failures;auto Check=[&](bool B,const FString& Label){++Checks;if(!B)Failures.Add(MakeShared<FJsonValueString>(Label));};
        Check(Catalog.IsValid()&&Object(Catalog,TEXT("effects"))->Values.Num()>5000,TEXT("original spell definition catalogue loaded"));
        auto Local=MakeShared<FJsonObject>();Local->SetStringField(TEXT("id"),TEXT("player:local"));Local->SetStringField(TEXT("kind"),TEXT("player"));Local->SetNumberField(TEXT("model_id"),0);Local->SetNumberField(TEXT("health"),1);Local->SetNumberField(TEXT("size"),50);S->EntityRows.Add(TEXT("player:local"),Local);Check(S->CreateEntity(TEXT("player:local"),Local,FVector::ZeroVector)!=nullptr,TEXT("original caster body loaded"));
        auto Target=MakeShared<FJsonObject>();Target->Values=Local->Values;Target->SetStringField(TEXT("id"),TEXT("npc:fx"));Target->SetStringField(TEXT("kind"),TEXT("npc"));Target->SetNumberField(TEXT("model_id"),118);S->EntityRows.Add(TEXT("npc:fx"),Target);Check(S->CreateEntity(TEXT("npc:fx"),Target,FVector(400,0,0))!=nullptr,TEXT("original target body loaded"));
        auto Snapshot=MakeShared<FJsonObject>();auto Event=MakeShared<FJsonObject>();Event->SetNumberField(TEXT("seq"),1);Event->SetStringField(TEXT("kind"),TEXT("cast"));Event->SetStringField(TEXT("caster"),TEXT("player:local"));Event->SetNumberField(TEXT("effect_id"),4101);Event->SetNumberField(TEXT("duration_ms"),3000);Event->SetNumberField(TEXT("age_ms"),200);Snapshot->SetArrayField(TEXT("spell_visuals"),{MakeShared<FJsonValueObject>(Event)});Apply(Snapshot);Check(Live.Num()==2,TEXT("real Gleam Ray definition produces both original hand glows"));Tick(0);Check(Particles>0,TEXT("original particle emitters generate visible sprite vertices"));
        for(auto& E:Live)for(auto& Part:E.Parts){Check(Part.Material.IsValid(),TEXT("original texture material loaded"));Check(Part.Mesh.IsValid()&&Part.Mesh->GetCollisionEnabled()==ECollisionEnabled::NoCollision,TEXT("spell visual cannot block movement, camera or LOS"));Check(Part.Created,TEXT("bounded procedural render section created"));}
        int32 Before=Created;Apply(Snapshot);Check(Created==Before,TEXT("repeated snapshots never duplicate effects"));Event->SetNumberField(TEXT("seq"),2);Event->SetStringField(TEXT("kind"),TEXT("cancel"));Apply(Snapshot);Check(Live.IsEmpty(),TEXT("interrupt removes original hand effects immediately"));
        Event->SetNumberField(TEXT("seq"),3);Event->SetStringField(TEXT("kind"),TEXT("release"));Event->SetStringField(TEXT("target"),TEXT("npc:fx"));Apply(Snapshot);Check(Live.Num()==2,TEXT("original cast burst and target impact created"));Tick(0);Check(Number(Local,TEXT("health"))==1&&Number(Target,TEXT("health"))==1,TEXT("visual rendering never changes health"));
        for(auto& E:Live)E.Began-=10;Tick(0);Check(Live.IsEmpty(),TEXT("expired visual actors and components removed"));
        Event->SetNumberField(TEXT("seq"),4);Event->SetNumberField(TEXT("effect_id"),4301);Event->SetStringField(TEXT("target"),TEXT("player:local"));Apply(Snapshot);Tick(0);bool MeshFound=false;for(auto& E:Live)for(auto& Part:E.Parts)if(!Part.Particle&&Part.Created)MeshFound=true;Check(MeshFound,TEXT("original powerward shield mesh is rendered, not substituted"));
        if(FParse::Param(FCommandLine::Get(),TEXT("DaocBridgeBainsheeEffectsTest"))){
            for(int32 Id:{13515,13516}){
                Clear();Event->SetNumberField(TEXT("seq"),1);Event->SetStringField(TEXT("kind"),TEXT("cast"));Event->SetNumberField(TEXT("effect_id"),Id);Event->SetStringField(TEXT("target"),TEXT("player:local"));Apply(Snapshot);Tick(0);
                Check(Live.Num()==2,TEXT("Bainshee absorption buff creates both original hand effects"));Check(Particles>0,TEXT("Bainshee original gather emitters create sprite vertices"));
                Event->SetNumberField(TEXT("seq"),2);Event->SetStringField(TEXT("kind"),TEXT("release"));Apply(Snapshot);Tick(0);
                Check(Live.Num()==2,TEXT("Bainshee absorption buff creates original burst and target shield"));bool Shield=false;
                for(auto& E:Live)for(auto& Part:E.Parts){Check(Part.Material.IsValid(),TEXT("Bainshee effect original material loaded"));Check(Part.Mesh.IsValid()&&Part.Mesh->GetCollisionEnabled()==ECollisionEnabled::NoCollision,TEXT("Bainshee effect cannot block movement or LOS"));Check(Part.Created,TEXT("Bainshee effect render section created"));if(!Part.Particle&&Part.Created)Shield=true;}
                Check(Shield,TEXT("Bainshee original shield mesh rendered"));Check(Number(Local,TEXT("health"))==1,TEXT("Bainshee visual never changes health"));
            }
            for(int32 Id:{3332,3334}){Clear();Event->SetNumberField(TEXT("seq"),1);Event->SetNumberField(TEXT("effect_id"),Id);Apply(Snapshot);Check(Live.IsEmpty(),TEXT("icon IDs are not silently treated as effect IDs"));}
        }
        if(FParse::Param(FCommandLine::Get(),TEXT("DaocBridgeWeaponVisualTest"))){
            Clear();auto* Body=Entity(TEXT("player:local"));auto Equip=[&](int32 Id,bool Drawn=true){for(auto& B:S->LocalEquipment)if(B.Value.Component.IsValid())B.Value.Component->DestroyComponent();S->LocalEquipment.Empty();auto Item=MakeShared<FJsonObject>();Item->SetNumberField(TEXT("model"),445);Item->SetNumberField(TEXT("effect"),Id);int32 MissingModel=0,MissingBone=0;return S->AttachEquipment(Body,10,Item,Drawn,S->LocalEquipment,MissingModel,MissingBone);};
            const auto WeaponDefs=Object(Catalog,TEXT("weapon_effects"));Check(WeaponDefs&&WeaponDefs->Values.Num()==94,TEXT("all original permanent weapon definitions loaded"));
            if(WeaponDefs)for(const auto& Def:WeaponDefs->Values){const int32 Id=FCString::Atoi(*Def.Key);Check(Equip(Id),FString(TEXT("original weapon attaches for effect "))+Def.Key);Tick(0);Tick(0);bool Built=Live.Num()==1&&Live[0].Weapon&&!Live[0].Parts.IsEmpty();if(Built)for(const auto& P:Live[0].Parts)Built&=P.Created&&P.Material.IsValid()&&P.Mesh.IsValid()&&P.Mesh->GetCollisionEnabled()==ECollisionEnabled::NoCollision;Check(Built,FString(TEXT("original permanent effect builds collision-free render sections: "))+Def.Key);}
            Equip(30);Tick(0);const int32 Once=Created;Tick(0);Check(Created==Once&&Live.Num()==1,TEXT("repeated snapshots never duplicate a permanent weapon effect"));
            if(Live.Num()==1){Live[0].Began-=10;Tick(0);Check(Live.Num()==1&&Particles>0,TEXT("permanent particles keep emitting beyond the spell emit window"));auto* Attachment=S->LocalEquipment[10].Component.Get();FTransform Expected=Live[0].WeaponFrame*Attachment->GetComponentTransform();Check(Live[0].Actor->GetActorTransform().Equals(Expected,.001),TEXT("effect uses the measured original weapon grip transform"));Body->AddActorWorldOffset(FVector(75,40,0));Tick(0);Expected=Live[0].WeaponFrame*Attachment->GetComponentTransform();Check(Live[0].Actor->GetActorTransform().Equals(Expected,.001),TEXT("weapon effect follows actor movement instead of floating in world space"));}
            Equip(30,false);Tick(0);Check(Live.Num()==1&&Live[0].Attachment==S->LocalEquipment[10].Component,TEXT("sheathing replaces the old anchor without leaving a floating effect"));
            Equip(999999);Tick(0);Check(Live.IsEmpty(),TEXT("unknown weapon effect does not invent a substitute"));Equip(0);Tick(0);Check(Live.IsEmpty(),TEXT("effect removal clears its actor immediately"));
            auto NpcRow=MakeShared<FJsonObject>();NpcRow->SetStringField(TEXT("id"),TEXT("npc:weapon-fx"));NpcRow->SetStringField(TEXT("kind"),TEXT("npc"));NpcRow->SetNumberField(TEXT("model_id"),1984);NpcRow->SetNumberField(TEXT("health"),1);NpcRow->SetNumberField(TEXT("size"),50);S->EntityRows.Add(TEXT("npc:weapon-fx"),NpcRow);auto* Npc=S->CreateEntity(TEXT("npc:weapon-fx"),NpcRow,FVector(400,0,0));Check(Npc!=nullptr,TEXT("original humanoid NPC available for permanent effect"));
            if(Npc){auto& State=S->RemoteEquipment.FindOrAdd(TEXT("npc:weapon-fx"));State.Actor=Npc;auto Item=MakeShared<FJsonObject>();Item->SetNumberField(TEXT("model"),19);Item->SetNumberField(TEXT("effect"),30);int32 MissingModel=0,MissingBone=0;Check(S->AttachEquipment(Npc,12,Item,true,State.Bindings,MissingModel,MissingBone),TEXT("NPC holds its own original staff effect"));Equip(1);Tick(0);Check(Live.Num()==2,TEXT("local and NPC weapon effects coexist independently"));Npc->SetActorLocation(FVector(50000,0,0));Tick(0);Check(Live.Num()==1&&Live[0].Owner==TEXT("player:local"),TEXT("distant NPC weapon effects are culled while local effect remains"));Npc->SetActorLocation(FVector(400,0,0));Tick(0);Check(Live.Num()==2,TEXT("returning NPC effect is restored once without duplicates"));Npc->Destroy();S->Entities.Remove(TEXT("npc:weapon-fx"));Tick(0);Check(Live.Num()==1,TEXT("NPC disappearance releases its permanent effect"));}
            const FString PreviousQuality=S->Quality;S->Quality=TEXT("accessible");Equip(1);
            for(int32 I=0;I<20;++I){const FString Id=FString::Printf(TEXT("npc:weapon-crowd-%d"),I);auto Row=MakeShared<FJsonObject>();Row->SetStringField(TEXT("id"),Id);Row->SetStringField(TEXT("kind"),TEXT("npc"));Row->SetNumberField(TEXT("model_id"),1984);Row->SetNumberField(TEXT("health"),1);Row->SetNumberField(TEXT("size"),50);S->EntityRows.Add(Id,Row);auto* Crowd=S->CreateEntity(Id,Row,FVector(400+I*30,0,0));if(!Crowd)continue;auto& State=S->RemoteEquipment.FindOrAdd(Id);State.Actor=Crowd;auto Item=MakeShared<FJsonObject>();Item->SetNumberField(TEXT("model"),445);Item->SetNumberField(TEXT("effect"),1);int32 MissingModel=0,MissingBone=0;S->AttachEquipment(Crowd,10,Item,true,State.Bindings,MissingModel,MissingBone);}
            Tick(0);Tick(0);Check(Live.Num()==8,TEXT("accessible quality bounds a crowd to eight permanent effects"));bool LocalVisible=false;for(const auto& E:Live)LocalVisible|=E.Owner==TEXT("player:local");Check(LocalVisible,TEXT("crowd limit preserves the local player's own weapon effect"));S->Quality=TEXT("balanced");Tick(0);Check(Live.Num()==16,TEXT("balanced quality allows sixteen permanent effects"));S->Quality=TEXT("high");Tick(0);Check(Live.Num()==21,TEXT("high quality keeps all twenty-one nearby sample weapons within its cap"));S->Quality=PreviousQuality;
        }
        S->ClearEntities();Check(Live.IsEmpty(),TEXT("session cleanup leaves no floating spell visuals"));auto O=MakeShared<FJsonObject>();O->SetBoolField(TEXT("passed"),Failures.IsEmpty());O->SetNumberField(TEXT("checks"),Checks);O->SetArrayField(TEXT("failures"),Failures);O->SetBoolField(TEXT("real_server"),false);return O;}
    J Report()const{auto O=MakeShared<FJsonObject>();O->SetBoolField(TEXT("catalog_loaded"),Catalog.IsValid());O->SetNumberField(TEXT("active_effects"),Live.Num());int32 WeaponCount=0;for(const auto& E:Live)if(E.Weapon)++WeaponCount;O->SetNumberField(TEXT("weapon_effects"),WeaponCount);O->SetNumberField(TEXT("created"),Created);O->SetNumberField(TEXT("culled"),Culled);O->SetNumberField(TEXT("active_particles"),Particles);O->SetNumberField(TEXT("last_ms"),LastMs);O->SetNumberField(TEXT("peak_ms"),PeakMs);return O;}
};
void UDAoCBridgeSubsystem::ApplySpellVisuals(const TSharedPtr<FJsonObject>& Snapshot){if(!SpellVisuals.IsValid())SpellVisuals=MakeShared<FBridgeSpellVisuals>(this);SpellVisuals->Apply(Snapshot);}
void UDAoCBridgeSubsystem::TickSpellVisuals(float Dt){if(SpellVisuals.IsValid())SpellVisuals->Tick(Dt);}
void UDAoCBridgeSubsystem::ClearSpellVisuals(){if(SpellVisuals.IsValid())SpellVisuals->Clear();}
TSharedPtr<FJsonObject> UDAoCBridgeSubsystem::SpellVisualReport()const{return SpellVisuals.IsValid()?SpellVisuals->Report():MakeShared<FJsonObject>();}

bool UDAoCBridgeSubsystem::TickSpellVisualAcceptance(){FString Path;if(!FParse::Value(FCommandLine::Get(),TEXT("DaocBridgeSpellVisualAcceptance="),Path))return false;static bool Ran=false;if(Ran)return true;Ran=true;if(!SpellVisuals.IsValid())SpellVisuals=MakeShared<FBridgeSpellVisuals>(this);auto Result=SpellVisuals->Test();FString Text;FJsonSerializer::Serialize(Result,TJsonWriterFactory<>::Create(&Text));FFileHelper::SaveStringToFile(Text,*Path);UKismetSystemLibrary::QuitGame(GetWorld(),GetWorld()->GetFirstPlayerController(),EQuitPreference::Quit,false);return true;}
